# 한 주간 급식 잔반량(kg)과 급식 만족도(점, 1~5점)
waste = {"월": 12, "화": 18, "수": 9, "목": 25, "금": 16}
score = {"월": 3.2, "화": 2.8, "수": 4.1, "목": 2.5, "금": 3.6}


def normalize(d):
    lo, hi = min(d.values()), max(d.values())
    return {k: round((v - lo) / (hi - lo), 2) for k, v in d.items()}


print("잔반량 정규화:", normalize(waste))
print("만족도 정규화:", normalize(score))
